class FoodRatings {
    private java.util.HashMap<String, String> foodCuisine;
    private java.util.HashMap<String, Integer> foodRating;
    private java.util.HashMap<String, java.util.TreeSet<String>> cuisineSet;

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        foodCuisine = new java.util.HashMap<>();
        foodRating = new java.util.HashMap<>();
        cuisineSet = new java.util.HashMap<>();
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            cuisineSet.computeIfAbsent(cuisines[i], k -> new java.util.TreeSet<>((a, b) -> {
                int ra = foodRating.getOrDefault(a, 0);
                int rb = foodRating.getOrDefault(b, 0);
                if (ra != rb) return rb - ra;
                return a.compareTo(b);
            })).add(foods[i]);
        }
    }

    public void changeRating(String food, int newRating) {
        String cuisine = foodCuisine.get(food);
        java.util.TreeSet<String> set = cuisineSet.get(cuisine);
        set.remove(food);
        foodRating.put(food, newRating);
        set.add(food);
    }

    public String highestRated(String cuisine) {
        return cuisineSet.get(cuisine).first();
    }
}

import java.util.*;

class FoodRatings {
    private Map<String, String> foodCuisine;
    private Map<String, Integer> foodRating;
    private Map<String, PriorityQueue<String[]>> cuisineHeap;

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        foodCuisine = new HashMap();
        foodRating = new HashMap();
        cuisineHeap = new HashMap();
        for (int i = 0; i < foods.length; i++) {
            foodCuisine.put(foods[i], cuisines[i]);
            foodRating.put(foods[i], ratings[i]);
            if (!cuisineHeap.containsKey(cuisines[i])) {
                cuisineHeap.put(cuisines[i], new PriorityQueue(new Comparator<String[]>() {
                    public int compare(String[] a, String[] b) {
                        int ra = Integer.parseInt(a[1]);
                        int rb = Integer.parseInt(b[1]);
                        if (ra != rb) return rb - ra;
                        return a[0].compareTo(b[0]);
                    }
                }));
            }
            cuisineHeap.get(cuisines[i]).offer(new String[]{foods[i], String.valueOf(ratings[i])});
        }
    }

    public void changeRating(String food, int newRating) {
        foodRating.put(food, newRating);
        String cuisine = foodCuisine.get(food);
        cuisineHeap.get(cuisine).offer(new String[]{food, String.valueOf(newRating)});
    }

    public String highestRated(String cuisine) {
        PriorityQueue<String[]> heap = cuisineHeap.get(cuisine);
        while (true) {
            String[] top = heap.peek();
            int currentRating = foodRating.get(top[0]).intValue();
            if (currentRating == Integer.parseInt(top[1])) return top[0];
            heap.poll();
        }
    }
}
